CREATE TYPE "MilestoneStatus" AS ENUM ('PENDING','IN_PROGRESS','COMPLETED','BLOCKED','CANCELLED');
CREATE TYPE "ReceiptStatus" AS ENUM ('PENDING','ACCEPTED','ISSUE_REPORTED');
CREATE TYPE "ClaimStatus" AS ENUM ('OPEN','UNDER_REVIEW','RESOLVED','REJECTED','CLOSED');
CREATE TABLE "TradeMilestone" ("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"code" TEXT NOT NULL,"label" TEXT NOT NULL,"sequence" INTEGER NOT NULL,"status" "MilestoneStatus" NOT NULL DEFAULT 'PENDING',"buyerVisible" BOOLEAN NOT NULL DEFAULT true,"targetAt" TIMESTAMP(3),"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"evidence" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TradeMilestone_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "TradeMilestone_transactionId_code_key" ON "TradeMilestone"("transactionId","code");CREATE UNIQUE INDEX "TradeMilestone_transactionId_sequence_key" ON "TradeMilestone"("transactionId","sequence");
CREATE TABLE "TradeReceipt" ("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"status" "ReceiptStatus" NOT NULL DEFAULT 'PENDING',"confirmedById" TEXT,"confirmedAt" TIMESTAMP(3),"notes" TEXT,"evidence" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TradeReceipt_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "TradeReceipt_transactionId_key" ON "TradeReceipt"("transactionId");
CREATE TABLE "TradeClaim" ("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"reference" TEXT NOT NULL,"status" "ClaimStatus" NOT NULL DEFAULT 'OPEN',"category" TEXT NOT NULL,"description" TEXT NOT NULL,"requestedResolution" TEXT,"evidence" JSONB,"resolution" JSONB,"openedById" TEXT,"resolvedById" TEXT,"resolvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TradeClaim_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "TradeClaim_reference_key" ON "TradeClaim"("reference");CREATE INDEX "TradeClaim_transactionId_status_idx" ON "TradeClaim"("transactionId","status");
CREATE TABLE "TradeMemory" ("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"buyerOrgId" TEXT NOT NULL,"productKey" TEXT NOT NULL,"approvedConfig" JSONB NOT NULL,"commercialHistory" JSONB NOT NULL,"executionHistory" JSONB NOT NULL,"sourceHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TradeMemory_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "TradeMemory_transactionId_key" ON "TradeMemory"("transactionId");CREATE INDEX "TradeMemory_buyerOrgId_productKey_updatedAt_idx" ON "TradeMemory"("buyerOrgId","productKey","updatedAt");
ALTER TABLE "TradeMilestone" ADD CONSTRAINT "TradeMilestone_transactionId_fkey" FOREIGN KEY ("transactionId") REFERENCES "TradeTransaction"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TradeReceipt" ADD CONSTRAINT "TradeReceipt_transactionId_fkey" FOREIGN KEY ("transactionId") REFERENCES "TradeTransaction"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TradeClaim" ADD CONSTRAINT "TradeClaim_transactionId_fkey" FOREIGN KEY ("transactionId") REFERENCES "TradeTransaction"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TradeMemory" ADD CONSTRAINT "TradeMemory_transactionId_fkey" FOREIGN KEY ("transactionId") REFERENCES "TradeTransaction"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
